package config

import (
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"strconv"
	"strings"
)

// Config intentionally exposes only the four bootstrap settings allowed by the
// deployment contract. Every mutable operating setting lives in PostgreSQL.
type Config struct {
	PostgresDSN            string
	BootstrapAdmin         string
	BootstrapAdminPassword string
	EncryptionKey          []byte
	// DrainSeconds is how long readiness reports failure before the listener
	// closes, giving whatever routes traffic here time to take this instance out
	// of rotation. Zero shuts down immediately, which is what a single instance
	// or a test wants.
	DrainSeconds int
}

func Load() (Config, error) {
	key, err := parseEncryptionKey(os.Getenv("ENCRYPTION_KEY"))
	if err != nil {
		return Config{}, err
	}
	cfg := Config{
		PostgresDSN:            strings.TrimSpace(os.Getenv("POSTGRES_DSN")),
		BootstrapAdmin:         strings.TrimSpace(os.Getenv("BOOTSTRAP_ADMIN")),
		BootstrapAdminPassword: os.Getenv("BOOTSTRAP_ADMIN_PASSWORD"),
		EncryptionKey:          key,
		DrainSeconds:           intFromEnv("SHUTDOWN_DRAIN_SECONDS", 5, 0, 120),
	}
	if cfg.PostgresDSN == "" || cfg.BootstrapAdmin == "" || cfg.BootstrapAdminPassword == "" {
		return Config{}, errors.New("POSTGRES_DSN, BOOTSTRAP_ADMIN, BOOTSTRAP_ADMIN_PASSWORD and ENCRYPTION_KEY are required")
	}
	if len(cfg.BootstrapAdminPassword) < 12 {
		return Config{}, errors.New("BOOTSTRAP_ADMIN_PASSWORD must be at least 12 characters")
	}
	return cfg, nil
}

func parseEncryptionKey(raw string) ([]byte, error) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return nil, errors.New("ENCRYPTION_KEY is required")
	}
	if decoded, err := base64.StdEncoding.DecodeString(raw); err == nil && len(decoded) == 32 {
		return decoded, nil
	}
	if decoded, err := hex.DecodeString(raw); err == nil && len(decoded) == 32 {
		return decoded, nil
	}
	return nil, fmt.Errorf("ENCRYPTION_KEY must be exactly 32 bytes encoded as base64 or 64 hexadecimal characters")
}

// intFromEnv keeps a bad value from becoming a startup failure: a deployment
// with a typo in an optional tuning knob should run with the default, not
// refuse to start.
func intFromEnv(name string, fallback, min, max int) int {
	value, err := strconv.Atoi(strings.TrimSpace(os.Getenv(name)))
	if err != nil || value < min || value > max {
		return fallback
	}
	return value
}
package config

import (
	"encoding/base64"
	"strings"
	"testing"
)

func TestLoadAcceptsExactlyTheBootstrapContract(t *testing.T) {
	t.Setenv("POSTGRES_DSN", "postgres://test")
	t.Setenv("BOOTSTRAP_ADMIN", "admin@example.test")
	t.Setenv("BOOTSTRAP_ADMIN_PASSWORD", "a-secure-password")
	t.Setenv("ENCRYPTION_KEY", base64.StdEncoding.EncodeToString([]byte(strings.Repeat("k", 32))))
	cfg, err := Load()
	if err != nil {
		t.Fatalf("Load(): %v", err)
	}
	if len(cfg.EncryptionKey) != 32 {
		t.Fatalf("key length=%d", len(cfg.EncryptionKey))
	}
}

func TestLoadRejectsWeakBootstrapPassword(t *testing.T) {
	t.Setenv("POSTGRES_DSN", "postgres://test")
	t.Setenv("BOOTSTRAP_ADMIN", "admin")
	t.Setenv("BOOTSTRAP_ADMIN_PASSWORD", "short")
	t.Setenv("ENCRYPTION_KEY", strings.Repeat("01", 32))
	if _, err := Load(); err == nil {
		t.Fatal("expected weak password error")
	}
}

func TestEncryptionKeyMustBe32Bytes(t *testing.T) {
	if _, err := parseEncryptionKey(base64.StdEncoding.EncodeToString([]byte("too short"))); err == nil {
		t.Fatal("expected key length error")
	}
}
package main

import (
	"context"
	"errors"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/hkjang/Kkiit/internal/config"
	"github.com/hkjang/Kkiit/internal/cryptox"
	"github.com/hkjang/Kkiit/internal/database"
	"github.com/hkjang/Kkiit/internal/httpapi"
	"github.com/hkjang/Kkiit/internal/worker"
)

var (
	version = "0.0.0-dev"
	commit  = "unknown"
	builtAt = "unknown"
)

func main() {
	logger := slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{Level: slog.LevelInfo}))
	cfg, err := config.Load()
	if err != nil {
		logger.Error("configuration error", "error", err)
		os.Exit(1)
	}
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()
	pool, err := database.Open(ctx, cfg.PostgresDSN)
	if err != nil {
		logger.Error("database unavailable", "error", err)
		os.Exit(1)
	}
	defer pool.Close()
	if err := database.Migrate(ctx, pool); err != nil {
		logger.Error("migration failed", "error", err)
		os.Exit(1)
	}
	if err := database.EnsureBootstrapAdmin(ctx, pool, cfg.BootstrapAdmin, cfg.BootstrapAdminPassword); err != nil {
		logger.Error("bootstrap admin failed", "error", err)
		os.Exit(1)
	}
	box, err := cryptox.New(cfg.EncryptionKey)
	if err != nil {
		logger.Error("encryption initialization failed", "error", err)
		os.Exit(1)
	}
	api := &httpapi.Server{DB: pool, Box: box, Version: version, Commit: commit, BuiltAt: builtAt, Logger: logger}
	dispatcher := &worker.Worker{DB: pool, Box: box, Logger: logger, Publish: api.PublishUser}
	api.Rescan = dispatcher.ScanNow
	api.SettingSaved = dispatcher.SettingSaved
	dispatcher.Maintenance = api.RunOrderMaintenance
	// The dispatcher claims events inside a transaction. Exiting without waiting
	// for it leaves that work to the stuck-event sweeper on the next start,
	// which recovers it but only after a delay nobody asked for.
	dispatcherDone := make(chan struct{})
	go func() {
		defer close(dispatcherDone)
		dispatcher.Run(ctx)
	}()
	server := &http.Server{Addr: ":8080", Handler: api.Handler(), ReadHeaderTimeout: 10 * time.Second, ReadTimeout: 30 * time.Second, WriteTimeout: 60 * time.Second, IdleTimeout: 2 * time.Minute, MaxHeaderBytes: 1 << 20}
	go func() {
		logger.Info("Kkiit started", "address", server.Addr, "version", version)
		if err := server.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			logger.Error("server stopped unexpectedly", "error", err)
			stop()
		}
	}()
	<-ctx.Done()
	// Readiness fails first and the socket stays open for a moment, so whatever
	// routes traffic here can take this instance out before it disappears. Going
	// straight to Shutdown means every request already on its way to this
	// process fails, which during a rolling deploy is every request.
	api.BeginDrain()
	logger.Info("draining before shutdown", "seconds", cfg.DrainSeconds)
	if cfg.DrainSeconds > 0 {
		time.Sleep(time.Duration(cfg.DrainSeconds) * time.Second)
	}
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
	defer cancel()
	if err := server.Shutdown(shutdownCtx); err != nil {
		logger.Error("graceful shutdown failed", "error", err)
	}
	select {
	case <-dispatcherDone:
	case <-time.After(15 * time.Second):
		logger.Warn("event dispatcher did not stop in time")
	}
	logger.Info("Kkiit stopped")
}
